function save(){try{localStorage.setItem('atlas-london-explore',JSON.stringify(s))}catch{}}
function note(id){if(!s.notes.includes(id)){s.notes.push(id);s.hours=Math.max(0,s.hours-2);toast('Clue added to notebook');save()}hud()}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');toastUntil=performance.now()+3200}
function hud(){$('#count').textContent=s.notes.length;$('#time').textContent=s.hours+'h left';$('#objective').textContent=s.solved?'London complete · Next stop: Lisbon':s.notes.length===0?'Find the museum guard':s.notes.length<3?'Search the district for more clues':'Compare your clues · Visit the travel clerk'}
function dialogue(who,text,choices=[['Back to the street',closeDialogue]]){dialogOpen=true;keys.clear();target=null;$('#speaker').textContent=who;$('#speech').textContent=text;const c=$('#choices');c.replaceChildren();for(const [label,fn] of choices){const b=document.createElement('button');b.textContent=label;b.onclick=fn;c.append(b)}$('#dialogue').hidden=false;$('#interact').hidden=true;c.querySelector('button')?.focus()}
function closeDialogue(){dialogOpen=false;$('#dialogue').hidden=true;canvas.focus({preventScroll:true})}
function interact(o=near){if(!o||dialogOpen||$('#book').open||!s.started)return;const known=s.notes.includes(o.id);
if(o.id==='guard'){if(known)return dialogue('Museum guard',evidence.guard.text);dialogue('Museum guard','The alarm sounded just after dawn. A courier hurried down these steps with a covered crate. They asked about a city beside the Tagus, and spoke Portuguese.',[['Ask about the destination',()=>dialogue('Museum guard · A question','Which country would you investigate based on those clues?',[['Portugal',()=>{note('guard');dialogue('Museum guard','Exactly. They also mentioned seven hills. I saw them stop at Café Meridian, across the square. Your notebook has my statement.')}],['Spain',()=>dialogue('Museum guard','The Tagus also flows through Spain, but Portuguese is the stronger clue here. Think about the country where it reaches the Atlantic.',[['Try again',()=>{closeDialogue();interact(o)}]])],['Italy',()=>dialogue('Museum guard','Italian would fit Italy, but this visitor spoke Portuguese. Try putting the language and river clues together.',[['Try again',()=>{closeDialogue();interact(o)}]])]])],['Leave',closeDialogue]])}
else if(o.id==='case'){note('case');dialogue('Discarded packing crate','Under the straw, you find the globe’s exhibition number and a silver compass pin tangled with green thread. Someone repacked the stolen artifact here.')}
else if(o.id==='owner'){note('owner');dialogue('Café owner','“Green eyes, a long coat. They ordered pastéis de nata with cinnamon. Said the ones back home were better. They left toward the fountain with a boarding pass in hand.”')}
else if(o.id==='ticket'){note('ticket');dialogue('Torn boarding pass','You lift a scrap from beside the fountain: destination code LIS. A handwritten message on the back reads, “The globe travels west. V.A.”')}
else if(o.id==='agent'){if(s.solved)return dialogue('Travel clerk','Your evidence points to Lisbon, Portugal. London is complete. The courier’s trail continues there. You can keep exploring and reviewing your notebook.');if(!s.notes.includes('guard')||s.notes.length<3)return dialogue('Travel clerk','“A hunch won’t book the right flight. Bring the guard’s statement and at least two more clues from the square, then tell me where the courier went.”');dialogue('Travel clerk · Deduction','A Portuguese-speaking courier. Seven hills on the Tagus. Custard tarts. Where does the evidence point?',[['Lisbon, Portugal',()=>{s.solved=true;save();hud();dialogue('London lead confirmed','Lisbon fits the language, river, seven hills, and LIS ticket code. Your findings are filed. This London prototype is complete — the next district will continue the pursuit.',[['Keep exploring',closeDialogue],['Review clues',()=>{closeDialogue();openBook()}]])}],['Madrid, Spain',()=>dialogue('Travel clerk','Madrid is inland and sits on the Manzanares. Compare the river, language, and food clues in your notebook.',[['Back to the street',closeDialogue]])],['Rome, Italy',()=>dialogue('Travel clerk','Rome has seven hills, but the river is the Tiber. Your other clues need to fit the same city.',[['Back to the street',closeDialogue]])]])}}
function openBook(){if(!s.started||dialogOpen)return;keys.clear();target=null;$('#notes').replaceChildren();if(!s.notes.length){const p=document.createElement('p');p.className='summary';p.textContent='No clues yet. The museum guard is waiting on the steps at the upper left of the square.';$('#notes').append(p)}for(const id of s.notes){const e=evidence[id];const a=document.createElement('article');a.className='note';const span=document.createElement('span');span.textContent=e.kind;const p=document.createElement('p');p.textContent=e.text;const small=document.createElement('small');small.textContent=e.title;a.append(span,p,small);$('#notes').append(a)}if(s.solved){const a=document.createElement('article');a.className='note';a.textContent='DEDUCTION CONFIRMED: Lisbon, Portugal. London investigation complete.';$('#notes').append(a)}$('#book').showModal()}
