window.addEventListener('keydown',e=>{if($('#book').open)return;if(dialogOpen){if(e.key==='Escape'){e.preventDefault();closeDialogue()}return}if(!s.started)return;const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright','w','a','s','d','e','n',' '].includes(k))e.preventDefault();if(k==='n'&&!e.repeat)openBook();else if((k==='e'||k===' ')&&!e.repeat)interact();else{keys.add(k);target=null;path=[]}});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();target=null;save()});document.addEventListener('visibilitychange',()=>{keys.clear();save()});
function blocked(x,y){if(x<34||x>926||y<74||y>568)return true;if(buildings.some(b=>x>b.x-10&&x<b.x+b.w+10&&y>b.y-6&&y<b.y+b.h+8))return true;return Math.hypot(x-468,(y-371)*1.45)<62||((x>76&&x<194&&y>397&&y<464))}
function findPath(x,y){
 const cell=16,start=[Math.round(s.x/cell),Math.round(s.y/cell)],goal=[Math.round(x/cell),Math.round(y/cell)];
 if(blocked(goal[0]*cell,goal[1]*cell))return [];
 const key=(a,b)=>a+','+b,queue=[start],seen=new Set([key(...start)]),prev=new Map();let found=false;
 for(let i=0;i<queue.length;i++){const [a,b]=queue[i];if(a===goal[0]&&b===goal[1]){found=true;break}for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=a+dx,ny=b+dy,k=key(nx,ny);if(!seen.has(k)&&!blocked(nx*cell,ny*cell)){seen.add(k);prev.set(k,[a,b]);queue.push([nx,ny])}}}
 if(!found)return [];let cur=goal,result=[];while(cur[0]!==start[0]||cur[1]!==start[1]){result.push({x:cur[0]*cell,y:cur[1]*cell});cur=prev.get(key(...cur));if(!cur)return []}return result.reverse();
}
