function frame(ms){const dt=Math.min((ms-last)/1000,.04);last=ms;moving=false;if(s.started&&!dialogOpen&&!$('#book').open){let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);if(target){dx=target.x-s.x;dy=target.y-s.y;if(Math.hypot(dx,dy)<4){target=path.shift()||null;dx=dy=0}}const len=Math.hypot(dx,dy);if(len){const ox=s.x,oy=s.y;move(dx/len*dt*115,dy/len*dt*115);moving=Math.abs(s.x-ox)+Math.abs(s.y-oy)>.05;if(target&&!moving)target=null}near=objects.reduce((best,o)=>Math.hypot(o.x-s.x,o.y-s.y)<61&&(!best||Math.hypot(o.x-s.x,o.y-s.y)<Math.hypot(best.x-s.x,best.y-s.y))?o:best,null);$('#interact').hidden=!near;if(near)$('#interact').innerHTML=`${near.action} ${near.label} <kbd>E</kbd>`}else $('#interact').hidden=true;if(ms>toastUntil)$('#toast').classList.remove('visible');if(ms-saveTick>1500){save();saveTick=ms}draw(ms/1000);requestAnimationFrame(frame)}
